"""Indonesian release manuals and actual recorded report examples."""
from pathlib import Path
import json
from xml.sax.saxutils import escape
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,PageBreak,Image
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.colors import HexColor
from reportlab.lib.pagesizes import A4
from .m12_release import ROOT,REL,APP,DOC
def pdf(name,title,sections):
 styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='BodyID',fontName='Helvetica',fontSize=10,leading=15,spaceAfter=10,textColor=HexColor('#233d45')))
 story=[Paragraph('GEDANGAN TRAFFIC SIMULATOR',styles['Title']),Paragraph(title,styles['Heading1']),Paragraph('EXTREME STUDIOS | v1.0.0<br/>PRESENTATION-READY ILLUSTRATIVE RELEASE',styles['BodyID']),Spacer(1,16)]
 for heading,paragraphs in sections:
  story.append(Paragraph(escape(heading),styles['Heading2']))
  for text in paragraphs:story.append(Paragraph(escape(text),styles['BodyID']))
 def footer(c,d):
  c.setFont('Helvetica',8);c.setFillColor(HexColor('#537078'));c.drawString(42,25,'Gedangan v1.0.0 | Simulasi ilustratif, belum dikalibrasi lapangan');c.drawRightString(A4[0]-42,25,str(d.page))
 SimpleDocTemplate(str(REL/'DOCUMENTATION'/name),pagesize=A4,leftMargin=42,rightMargin=42,topMargin=40,bottomMargin=44,title=title,author='EXTREME STUDIOS').build(story,onFirstPage=footer,onLaterPages=footer)
def main():
 quick=[('1. Ekstrak seluruh ZIP',['Klik kanan ZIP, pilih Extract All. Simpan di folder lokal yang dapat ditulis, misalnya Documents/Gedangan. Jangan membuka EXE langsung dari dalam ZIP. Pertahankan APPLICATION dan semua folder pendamping.']),('2. Buka aplikasi',['Klik dua kali APPLICATION/GEDANGAN_TRAFFIC_SIMULATOR.exe atau START_GEDANGAN_TRAFFIC_SIMULATOR.bat. Tidak perlu Python, Node, SUMO, Codex, atau internet. Microsoft Edge atau Chrome dengan WebGL2 perlu sudah terpasang. Browser bukan bagian paket. Tidak diperlukan akses administrator.']),('3. Jalankan demo',['Pilih 3D SIMULATION. Tunggu rekaman dimuat, lalu tekan Play. Pilih tahun 2026, 2030, 2035 atau 2040, demand dan skenario. Kamera Railway crossing menampilkan perlintasan. Timeline dan Play/Pause memakai jejak SUMO aktual.']),('4. Bandingkan dan presentasikan',['Pilih skenario S01, lalu COMPARISON. Kedua panel memakai waktu yang sama. Pilih PRESENTATION untuk sepuluh bagian terpandu. Tombol Slide teknis membuka 15 slide M11. PDF dan MP4 ada dalam paket sebagai cadangan.']),('5. Ekspor dan tutup',['REPORTS menyediakan PDF, CSV dan JSON untuk run terpilih. Akhiri dengan Tutup layanan atau STOP_GEDANGAN_TRAFFIC_SIMULATOR.bat. Menutup tab saja tidak mematikan layanan.']),('Batas penggunaan',['Status model: ilustratif dan provisional. Baseline empiris BLOCKED - DATA REQUIRED. Flyover dan underpass CONCEPT ONLY. Hasil belum membuktikan efektivitas solusi di lapangan.'])]
 pdf('QUICK_START_ID.pdf','Panduan mulai cepat',quick)
 user=quick[:2]+[('3. Mengenali dashboard',['OVERVIEW menunjukkan rekaman, tahun yang didukung dan status baseline. Status data tetap ditampilkan selama aplikasi dipakai. Delapan menu utama mengakses fungsi nyata; panel analisis teknis tidak dibuka sebagai default.']),('4. Simulasi dan tahun',['3D SIMULATION menyediakan tahun 2026-2040 dan LOW/REFERENCE/HIGH. Hanya 23 kombinasi yang memiliki rekaman. Tahun lain tetap NOT RUN, bukan diisi hasil lain. TRAFFIC GROWTH merangkum rekaman baseline dan mengarahkan ke kontrol tahun.']),('5. Memilih skenario',['SOLUTIONS menampilkan status S00-S07. S01-S04 memiliki eksperimen provisional yang tersedia. S05 diblokir; S06/S07 berupa konsep tanpa hasil efektivitas. Periksa label run sebelum memutar.']),('6. Kamera, playback dan kualitas',['Pilih aerial, main corridor, junction, railway, frontage, follow vehicle, atau orbit. Pilih kendaraan untuk close-up; ikuti kendaraan yang aktif. Play/Pause, reset, kecepatan dan slider tidak mengubah hasil SUMO. Fullscreen memperbesar tampilan. Balanced default memakai rasio piksel 1; Performance 0,75; Presentation 1,5. Perubahan kualitas memuat ulang view dan mengembalikan pilihan awal.']),('7. Perbandingan solusi',['Pilih tahun/demand dan intervensi, lalu COMPARISON. Baseline dan intervensi harus punya cohort, seed dan horizon sama. Bandingkan arrived bersama waiting, rute gagal, belum berangkat dan masih berjalan. Lebih sedikit tiba tidak boleh ditampilkan sebagai kemenangan.']),('8. Presentasi teknis',['PRESENTATION menuntun sepuluh topik dengan tombol Berikut dan kembali. Tombol Slide teknis membuka HTML M11 yang mempunyai 15 slide dan mode narasi. Folder PRESENTATION menyimpan PPTX/PDF/naskah 5 dan 15 menit. Video Full HD berada di VIDEO. PPTX memerlukan aplikasi pembaca Office; PDF/HTML/video dapat dibuka dengan browser.']),('9. Mengekspor laporan',['Buka REPORTS. Pilih run dan jenis Eksekutif, Teknis atau Perbandingan. Klik Ekspor PDF/CSV/JSON. Berkas masuk ke Downloads browser. Setiap ekspor memakai data aktual serta label ilustratif; PDF teknis menyertakan hash network/cohort dan diagnostik antrean.']),('10. Field survey',['FIELD DATA membuka workbench M08.5. Gunakan sesi latihan sintetis untuk belajar. Input tersebut tidak menjadi pengamatan Gedangan. Daftarkan pengamat, lakukan reconnaissance, dokumentasikan izin dan tinjau lokasi sebelum sesi field. Kelas, arah, gerakan, clock WIB, visibility dan coverage harus benar.']),('11. Counting dan video',['Pilih sesi IN_PROGRESS, lalu Manual Traffic Counter. Tombol kelas atau shortcut angka mencatat kejadian. Jeda sesi menghentikan count; Resume melanjutkan. Untuk video, pilih file lokal, tunggu hash selesai dan register. File asli tetap di komputer; aplikasi menyimpan referensi/anotasi. Rewind tidak menghapus ledger atau mengizinkan count token yang sama.']),('12. Menyimpan dan memulihkan',['Kejadian masuk IndexedDB browser terlebih dahulu, lalu SQLite setelah layanan mengonfirmasi. Jika antrean belum kosong, jangan menghapus profil/browser data. Kirim ulang antrean setelah layanan pulih. Simpan checkpoint; Data Validation & Export dapat membuat backup ZIP SQLite. Restore selalu membuat cabang baru dan mempertahankan cabang lama.']),('13. QC dan pembaruan baseline',['Ekspor sesi membuat CSV, JSON dan preview importer M06 di USER_DATA/surveys/exports/<id>. Raw events, koreksi dan provenance ikut disimpan. Missing bukan nol; count parsial tidak menjadi volume lengkap. Review bukti dan data tidak otomatis mengkalibrasi model. Eksekusi kalibrasi dan simulasi baru memerlukan toolchain riset terpisah setelah QC; paket playback ini tidak menyertakan SUMO executable.']),('14. Troubleshooting',['Jika aplikasi tidak terbuka, ekstrak ulang seluruh ZIP. Jangan memindahkan EXE sendirian. Lihat USER_DATA/last-error.txt atau bootstrap-error.txt. Jika port dipakai salinan lain, tutup salinan itu dahulu. Jangan mematikan service lain atau mengubah firewall. Jika WebGL tidak tersedia, gunakan PDF/HTML/MP4. Jika gambar tersendat, pilih Performance. Jika survei belum terkirim, pertahankan profil browser dan gunakan Kirim ulang antrean.']),('15. Backup dan privasi',['Tutup layanan sebelum menyalin seluruh USER_DATA. Backup video asli secara terpisah sesuai izin dan retention. Aplikasi hanya mendengar di loopback 127.0.0.1; ponsel fisik tidak bisa mengakses server ini lewat Wi-Fi. Pengujian mobile adalah viewport browser, bukan instalasi telepon. Jangan mengubah binding jaringan tanpa penilaian akses/privasi.'])]
 pdf('USER_MANUAL_ID.pdf','Manual pengguna',user)
 technical=[('Arsitektur distribusi',['APPLICATION berisi frozen Windows x64 host dan _internal Python runtime, frontend M10 serta M08.5 yang byte-identical, cache 23 rekaman dan adapter M12. Tidak diperlukan environment pengembangan. Microsoft Edge atau Chrome dengan WebGL2 adalah prerequisite yang tidak dibundel. Build menggunakan PyInstaller one-directory, bukan single-file mandiri. EXE harus tetap bersama _internal dan data pendamping.']),('Sumber dan baseline immutable',['documentation/m12/BASELINE_SHA256.json mengunci 9.236 berkas sebelum pekerjaan rilis. M12 menambah namespace baru dan folder FINAL_RELEASE; M01-M11 tidak ditimpa. Host hanya menulis ke USER_DATA dan tidak menjalankan generator lama. Runtime-manifest mencakup hash aset dan binary; preflight memverifikasi setiap index, chunk dan scene.']),('Lifecycle dan keamanan host',['Host loopback default 5192 dengan Host/Origin checks. Service dikenali lewat versi dan root_id salinan distribusi. Salinan di folder lain tidak boleh menggunakan service salinan pertama. Startup menghindari duplikasi melalui pemeriksaan service dan binding port. Shutdown menggunakan token sesi dan menutup server dengan bersih. Tidak ada perubahan firewall.']),('Rekaman dan integritas SUMO',['SUMO 1.28.0 adalah engine otoritatif. Frontend hanya memutar trace FCD aktual 0,5 detik dengan event signal/railway 1 detik dan alignment +0,5 detik. Tidak ada spawning palsu, override vehicle permissions atau routing baru pada runtime release. Network, OD demand dan vehicle registry tetap bersumber dari milestone lama.']),('Definisi accounting',['Requested = Routable + Failed routes. Routable = Departed + Not departed. Departed = Arrived + Running at end. Not arrived = Requested - Arrived. Horizon 2.100 detik. Running at end berbeda dari route failure. Waiting dan queue extent adalah diagnostik model dengan kemungkinan censoring.']),('Perbandingan yang sah',['Pasangan wajib memiliki tahun, growth, cohort SHA-256, seed dan horizon sama. Baseline 2026 S00: requested 240, routable 206, route failure 34, departed 206, arrived 183, running 23. Contoh 2040 HIGH S00/S01 menghasilkan arrived 356/328; delta -28 merupakan penurunan hasil pada simulasi ini.']),('Survei, ekspor dan versi data',['M08.5 menggunakan SQLite WAL dengan raw/audit append-only dan idempotent commands. Browser IndexedDB menyimpan antrean yang belum dikonfirmasi. Ekspor setiap sesi punya UUID, hashes, raw/corrections dan preview importer asli M06 di staging terpisah. Restore membuat database cabang baru. Dataset latihan tetap SYNTHETIC_TEST/DEMO_SYNTHETIC.']),('Pembaruan baseline setelah data tersedia',['Urutan operasional: reconnaissance dan izin; observasi; coverage; review independen; validasi sumber dan clock; ekspor M06; periksa accepted/rejected; simpan dataset berversi; jalankan toolchain riset M06/SUMO pada salinan kerja baru; evaluasi observed-versus-simulated serta holdout; simpan baseline baru dengan provenance; baru bangun rekaman/scenario comparison baru. Paket ini menyiapkan data, tidak mengeksekusi SUMO atau kalibrasi otomatis. Empirical calibration tetap BLOCKED sebelum bukti QC lengkap.']),('Lisensi dan distribusi',['Python, SQLite, ReportLab, Pillow, jsonschema dan frontend libraries disertai notis lokal. PyInstaller bootloader mempunyai distribution exception. OSM attribution dipertahankan. Aset research, raw video lapangan, node_modules, virtualenv, SUMO toolchain dan full workspace tidak dibundel. Tidak ada billing/service cloud.']),('Pengujian dan batas acceptance',['Lihat QA_EVIDENCE dan M12_QA_REPORT.md untuk hasil aktual. Hardware WMI dan browser renderer dicatat; AdapterRAM WMI bukan bukti VRAM fisik yang akurat. Rehearsal M11 tetap bukti terpisah. Uji manusia, proyektor fisik dan verifikasi kondisi lapangan tidak digantikan tes otomatis. Binary belum ditandatangani sertifikat penerbit.'])]
 pdf('TECHNICAL_MANUAL_ID.pdf','Manual teknis',technical)
 from .m12_host import pdf_bytes,report_data
 for kind in ['executive','technical','comparison']:
  d=report_data({'run':['9c9e07a0a18d0cfec64f'],'kind':[kind]});(REL/'REPORTS'/('CONTOH_'+kind.upper()+'.pdf')).write_bytes(pdf_bytes(d));(REL/'REPORTS'/('CONTOH_'+kind.upper()+'.json')).write_text(json.dumps(d,indent=2,ensure_ascii=False),encoding='utf-8')
 print('3 Indonesian manuals and 3 actual-data report PDFs created')
if __name__=='__main__':main()
